        m, n = len(p), len(s)
        if m > n:
            return []
        need = [0] * 26
        for ch in p:
            need[ord(ch) - 97] += 1
        win = [0] * 26
        out = []
        for i, ch in enumerate(s):
            win[ord(ch) - 97] += 1
            if i >= m:
