class Solution:
    def generateParenthesis(self, n):
        out, path = [], []

        def go(opened, closed):
            if closed == n:
                out.append("".join(path))
                return
            if opened < n:
                path.append("(")
                go(opened + 1, closed)
                path.pop()
            if closed < opened:
                path.append(")")
                go(opened, closed + 1)
                path.pop()

        go(0, 0)
        return out

