class Solution:
    def decodeString(self, s):
        st = []              # (text before '[', repeat count)
        cur, num = [], 0
        for ch in s:
            if ch.isdigit():
                num = num * 10 + int(ch)
            elif ch == "[":
                st.append((cur, num))
                cur, num = [], 0
            elif ch == "]":
                prev, k = st.pop()
                prev.append("".join(cur) * k)
                cur = prev
            else:
                cur.append(ch)
        return "".join(cur)

