        best = -1
        total = left = 0
        for right, v in enumerate(nums):
            total += v
            while total > target:
                total -= nums[left]
                left += 1
            if total == target and right - left + 1 > best:
                best = right - left + 1
        return -1 if best < 0 else len(nums) - best

