maximal-rectangle.solution:
class Solution:
    def maximalRectangle(self, matrix):
        if not matrix or not matrix[0]:
            return 0
        n = len(matrix[0])
        heights = [0] * (n + 1)          # last slot stays 0: the sentinel
        best = 0
        for row in matrix:
            for j in range(n):
                heights[j] = heights[j] + 1 if row[j] == "1" else 0
            st = []
            for i in range(n + 1):
                h = heights[i]
                while st and heights[st[-1]] >= h:
                    top = heights[st.pop()]
                    left = st[-1] if st else -1
                    area = top * (i - left - 1)
                    if area > best:
                        best = area
                st.append(i)
        return best

