class Solution:
    def findPeakElement(self, nums):
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < nums[mid + 1]:
                lo = mid + 1          # going uphill: a peak lies to the right
            else:
                hi = mid              # going downhill: mid itself or something to the left
        return lo

guide.approach:
