import bisect

class Solution:
    def successfulPairs(self, spells, potions, success):
        potions = sorted(potions)
        n = len(potions)
        out = []
        for s in spells:
            need = (success + s - 1) // s            # smallest potion strength that works (ceiling)
            out.append(n - bisect.bisect_left(potions, need))
        return out

