magnetic-force-between-two-balls.solution:
class Solution:
    def maxDistance(self, position, m):
        pos = sorted(position)

        def can(gap):
            placed, last = 1, pos[0]
            for p in pos:
                if p - last >= gap:
                    placed += 1
                    if placed == m:
                        return True
                    last = p
            return placed >= m

        lo, hi = 1, (pos[-1] - pos[0]) // (m - 1)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

