minimum-number-of-days-to-make-m-bouquet.solution:
class Solution:
    def minDays(self, bloomDay, m, k):
        if m * k > len(bloomDay):
            return -1

        def bouquets(day):
            made = run = 0
            for b in bloomDay:
                if b <= day:
                    run += 1
                    if run == k:
                        made += 1
                        run = 0
                else:
                    run = 0
            return made

        lo, hi = min(bloomDay), max(bloomDay)
        while lo < hi:
            mid = (lo + hi) // 2
            if bouquets(mid) >= m:
                hi = mid
            else:
                lo = mid + 1
        return lo
